import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.BKeRpnBD.js";const u=JSON.parse('{"title":"乾下巽上 小畜：","description":"京氏易传 - 乾下巽上 小畜：","frontmatter":{"title":"乾下巽上 小畜：","description":"京氏易传 - 乾下巽上 小畜："},"headers":[],"relativePath":"zh/classics/jingshi/043.md","filePath":"zh/classics/jingshi/043.md"}'),i={name:"zh/classics/jingshi/043.md"};function r(c,a,o,p,d,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"乾下巽上-小畜",tabindex:"-1"},[l("乾下巽上 小畜： "),e("a",{class:"header-anchor",href:"#乾下巽上-小畜","aria-label":"Permalink to “乾下巽上 小畜：”"},"​")],-1),e("p",null,"《易》云：“密云不雨，自我西郊”。小畜之义，在于六四。三阳连，进于一，危也。外巽体阴，畜道行也。巽之初六，阴荡阳气感，积阴不能固，退复本位。三连同往而不可见，成于畜义，外象明矣。【一阴劣，不能固，阳是以往也。外巽积阴能固，阳道成在上九一爻之法也。】《易》云：“既雨既处”也。与乾为飞伏。【甲子水，辛丑土。】初九元士居世，六四诸侯在应。",-1),e("p",null,"建始壬寅至丁未，【立春，大暑。】积算起丁未至丙午，周而复始。木土入乾巽。【入宫起算法。】",-1),e("p",null,"五星从位起太白，【金星入卦，起算吉凶。】尾宿从位降甲子，【二十八宿入卦，分尾宿，以小畜甲子水上起算。】分气候其数二十八。【分二十八数起宫推算。】",-1),e("p",null,"一阴居六四，建子入阳宫，推其休咎处吉凶。刚健立阳爻，阴凝在巽体。《易》云：“舆说辐，夫妻反目”。【不义之兆。】夏至起纯阴，阳爻位伏藏；冬至阳爻动，阴气凝地。",-1),e("p",null,"阴阳升降，以柔为刚，见中虚文明，积气居内象。【九二适变入离。】次降入风火家人卦。",-1)])])}const _=s(i,[["render",r]]);export{u as __pageData,_ as default};
